function [dj, de] = kozai_rates(j, e, nhat, phi_q)
%KOZAI_RATES  thirdbody.secular.kozaiRates(j, e, nhat, phiQ): the doubly-averaged quadrupole rates of j and e for one perturber
%   whose orbit's pole is nhat, at the secular frequency phi_q [rad/s].
%   j: real[1][3] (passed a plain number)
%   e: real[1][3] (passed a plain number)
%   nhat: real[1][3] (passed a plain number)
%   phi_q: real[1] (passed a plain number)
%   returns dj: real[1][3] (passed a plain number)
%   returns de: real[1][3] (passed a plain number)
%   Generated by tools/pcode.py from the pseudocode (trinetra-pcode/2); do not edit.
    dj = zeros(3, 1);
    de = zeros(3, 1);
    nn = asils.pc.norm_(nhat);
    n = [(nhat(1) / nn); (nhat(2) / nn); (nhat(3) / nn)];
    jn = asils.pc.dot_(j, n);
    en = asils.pc.dot_(e, n);
    jxn = asils.pc.cross_(j, n);
    exn = asils.pc.cross_(e, n);
    jxe = asils.pc.cross_(j, e);
    dj = zeros(3, 1);
    de = zeros(3, 1);
    for i = (0):((3) - 1)
        dj((i) + 1) = (phi_q * ((jn * jxn((i) + 1)) - ((5 * en) * exn((i) + 1))));
        de((i) + 1) = (phi_q * (((jn * exn((i) + 1)) + (2 * jxe((i) + 1))) - ((5 * en) * jxn((i) + 1))));
    end
end
